    type: "single",
    stem: "浮点数加、减运算过程一般包括对阶、尾数运算、规格化、舍入和判溢出等步骤。设浮点数的阶码和尾数均采用补码表示，且位数分别为 5 位和 7 位（均含 2 位符号位）。若有两个数 X=2⁷×29/32，Y=2⁵×5/8，则用浮点加法计算 X+Y 的最终结果是（）。",
    options: [{ key: "A", text: "00111 1100010" }, { key: "B", text: "00111 0100010" }, { key: "C", text: "01000 0010001" }, { key: "D", text: "发生溢出" }],
    answer: ["D"],
    explanation: "本题考查浮点数加减。X 的浮点数格式为 00,111;00,11101（分号前为阶码，分号后为尾数），Y 的浮点数格式为 00,101;00,10100。然后根据浮点数的加法步骤进行运算。\n\n第一步：对阶。X、Y 阶码相减，即 00,111-00,101 = 00,111+11,0111 = 00,010，可知 X 的阶码比 Y 的阶码大 2（这一步可直接目测）。根据小阶向大阶看齐的原则，将 Y 的阶码加 2，尾数右移 2 位，将 Y 变为 00,111；00,00101。\n\n第二步：尾数相加。即 00,11101+00,00101 = 01,00010，尾数相加结果符号位为 01，故需右规。\n\n第三步：规格化。将尾数右移 1 位，阶码加 1，得 X+Y 为 01,000;00,10001。\n\n第四步：判溢出。阶码符号位为 01，说明发生溢出。\n\n本题容易误选选项 B、C, 这是因为选项 B、C 本身并没有计算错误，只是它们不是最终结果，选项 B 少了第 3 步和第 4 步，选项 C 少了第 4 步。\n\n【偷懒法】本题也可以直接用数学知识对原数进行计算，然后将计算的结果转换成浮点数的格式。X+Y =\n29/32×27+5/8×25=29/32×27+5/32×27=(29/32+5/32)×27=34/32×27=17/32×28\n，阶码用补码表示，数值位 3 位，最大只能表示 7，即 X+Y 的结果的阶码 8 超出了该浮点数的表示范围，故溢出。",
    difficulty: "medium",
    tags: ["浮点数加减", "计算机组成原理", "2009 年真题"],
    sourceKey: "csgraduates-408",
