    stem: "一个 TCP 连接总是以 1KB 的最大段长发送 TCP 段，发送方有足够多的数据要发送。当拥塞窗口为 16KB 时发生了超时，如果接下来的 4 个 RTT（往返时间）时间内的 TCP 段的传输都是成功的，那么当第 4 个 RTT 时间内发送的所有 TCP 段都得到肯定应答时，拥塞窗口大小是（）。",
    options: [{ key: "A", text: "7 KB" }, { key: "B", text: "8 KB" }, { key: "C", text: "9 KB" }, { key: "D", text: "16 KB" }],
    answer: ["C"],
    explanation: "在发生超时后，慢开始门限 ssthresh 变为 16KB/2 = 8KB，拥塞窗口变为 1KB。在接下来的 3 个 RTT 内，执行慢开始算法，拥塞窗口大小依次为 2KB、4KB、8KB，由于慢开始门限 ssthresh 为 8KB，因此之后转而执行拥塞避免算法，即拥塞窗口开始“加法增大”。因此第 4 个 RTT 结束后，拥塞窗口的大小为 9KB。",
    difficulty: "medium",
    tags: ["TCP拥塞控制", "计算机网络", "2009 年真题"],
    sourceKey: "csgraduates-408",
