    options: [{ key: "A", text: "③→①→②→④" }, { key: "B", text: "②→③→①→④" }, { key: "C", text: "②→①→③→④" }, { key: "D", text: "①→②→④→③" }],
    answer: ["B"],
    explanation: "在开始 DMA 传输时，主机向内存写入 DMA 命令块，向 DMA 控制器写入该命令块的地址，启动 I/O 设备。然后，CPU 继续其他工作，DMA 控制器则继续下去直接操作内存总线，将地址放到总线上开始传输。当整个传输完成后，DMA 控制器中断 CPU。因此执行顺序是 ②→③→①→④ 选 B。",
    difficulty: "medium",
