    explanation: "存取时间 = 寻道时间 + 延迟时间 + 传输时间。存取一个扇区的平均延迟时间为旋转半周的时间，即为 (60/7200)/2=4.17ms，传输时间为 (60/7200)/1000=0.01ms，因此访问一个扇区的平均存取时间为 4.17+0.01+8=12.18ms，保留一位小数则为 12.2ms。",
    difficulty: "medium",
    tags: ["磁盘性能指标", "计算机组成原理", "2015 年真题"],
    sourceKey: "csgraduates-408",
