    explanation: "在程序中断方式中，CPU 和打印控制接口（I/O 端口）之间常见的交互信息包括：\n\nA. 打印字符：✅\nCPU 通过 I/O 端口向打印机发送要打印的字符数据。\n\nC. 设备状态：✅\nCPU 可以从设备读取其状态（如“忙碌”、“准备好”、“出错”等），判断是否可以继续发送数据。\n\nD. 控制命令：✅\nCPU 可以向设备发送控制命令（如“启动打印”、“复位”等）控制设备的行为。\n\n所以 B 选项错误，主存地址属于内存地址空间，而不是 I/O 端口和控制接口之间直接交换的信息。\n\n在中断 I/O 方式中：\n\n数据是由 CPU 从内存中取出，然后通过 I/O 指令送到 I/O 端口；\n\n并不是由 CPU 告诉 I/O 接口一个内存地址，让设备自己去内存取数据（那是 DMA 的行为）。\n\n因此，中断 I/O方式下不会在 CPU 和设备控制器之间交换主存地址。",
