    topicKey: "ex408g-ds-linearlist",
    type: "single",
    stem: "已知表头元素为 c 的单链表在内存中的存储状态如下表所示。现将 f 存放于 1014H 处并插入单链表，若 f 在逻辑上位于 a 和 e 之间，则 a,e,f 的 “链接地址” 依次是（）。 a 1010H b 100CH c 1000H d NULL e 1004H 元素 链接地址 地址 1000H 1004H 1008H 100CH 1010H 1014H",
