    options: [{ key: "A", text: "(0, 0), (0, 1), (1,0), (1, 1)" }, { key: "B", text: "(0, 0), (1, 0), (0, 1), (1, 1)" }, { key: "C", text: "(0, 0), (0, 1), (1, 1), (1, 0)" }, { key: "D", text: "(0, 0), (1, 1), (0, 1), (1, 0)" }],
