    stem: "已知 float 型变量用 IEEE754 单精度浮点数格式表示。若 float 型变量 x 的机器数为 8020 0000H，则 x 的值（）",
    options: [{ key: "A", text: "−2−128" }, { key: "B", text: "−1.01×2−127" }, { key: "C", text: "−1.01×2−126" }, { key: "D", text: "非数 (NAN)" }],
