    explanation: "本题考查浮点数表示的异常值，给定的机器数为 8020 0000H，表示一个 32 位的二进制数。我们需要将其转换为 float 型变量的值。8020 0000H = 1000 0000 0010 0000 0000 0000 0000 0000B。根据 IEEE754 单精度\n浮点数格式，首位表示符号位，接下来的 8 位表示指数部分，剩下的 23 位表示尾数部分。拆\n分该二进制表示，我们得到以下部分，符号位：1（表示负数），指数部分：00000000B（十进制值\n为 0)。尾数部分：010 0000 0000 0000 0000 0000B。本题考查的点为 IEEE 754 单精度点数的表\n示，因为指数部分为 0，尾数部分不为 0，所以为非规格化的表示，所以尾数部分的形式为 0.M\n不是 1.M，同时指数部分是 -126，而不是 -127，则真值为\n−0.01×2−126=−2−128\n，正确答案为 A 选项。",
    difficulty: "medium",
    tags: ["IEEE浮点数表示", "计算机组成原理", "2023 年真题"],
    sourceKey: "csgraduates-408",
