    explanation: "物理内存大小为\n16GB\n，每页大小为\n4KB\n，因此物理内存总共包含的页框数为\n(16GB)/(4KB)=234/212=222\n。位图需要管理每个页框的空闲状态，因此位图的位数应该等于物理\n内存中页框的数量。每个位表示一个页框的空闲状态，所以位图所占空间大小应为\n（位图所占位数）/8=(222)/8=219bytes=512KB\n，因此，位图所占空间的大小为\n512KB\n，选项\nC\n为正确答案。",
