    options: [{ key: "A", text: "80.02ms" }, { key: "B", text: "80.08ms" }, { key: "C", text: "80.09ms" }, { key: "D", text: "80.10ms" }],
    answer: ["D"],
    explanation: "参数\n\n计算\n\n结果\n\n链路带宽\nR\n\n—\n\n100Mbps\n\n时延带宽积RTp​\n\n题设给定\n\n1000bit\n\n传播时延\nTp​\n\nTp​=100Mbps1000bit​\n\n0.01 ms\n\n分组大小\nL\n\n—\n\n1000B=8000bit\n\n发送时延\nTs​\n\nTs​=RL​=100Mbps8000bit​\n\n0.08 ms\n\n分组数量\nN\n\nN=1000B1MB​\n\n1000\n\n发送阶段\n\n第 1 个分组：\n0→0.08\nms 发送完。\n\n…\n\n第 1000 个分组：\n79.92→80\nms 发送完。\n\n因此，最后 1 位比特离开 H1 的时刻为\nt1​=80 ms\n。\n\nH1 → R 传播\n\n单向传播时延\nTp​=0.01\nms\nt2​=t1​+Tp​=80.01 ms\n\nR 转发（序列化）\n\n路由器必须将该分组重新发送一次，耗时仍为\nTs​=0.08\nms\nt3​=t2​+Ts​=80.09 ms\n\nR → H2 传播\n\n再次经过链路传播时延\nTp​=0.01\nms\nt4​=t3​+Tp​=80.10 ms\n\n所以答案选择 D。",
    difficulty: "medium",
    tags: ["通信指标", "计算机网络", "2023 年真题"],
    sourceKey: "csgraduates-408",
