    answer: ["B"],
    explanation: "关于文件系统能为温彻斯特硬盘（HDD）和固态硬盘（SSD）提供的功能，分析如下：\n\nA. 划分扇区‌\n扇区是磁盘物理结构的固有属性，由硬盘制造商在出厂时划分，文件系统不参与扇区的物理划分。\n\nB. 确定盘块大小‌\n文件系统通过逻辑格式化设定文件存储的基本单位（如 4KB 的块大小），这是文件系统对物理存储的逻辑抽象，适用于 HDD 和 SSD。\n\nC. 降低寻道时间‌\n寻道时间是 HDD 特有的机械性能指标，文件系统无法直接优化；而 SSD 无机械部件，不存在寻道时间问题。\n\nD. 实现均衡磨损‌\n这是 SSD 特有的功能，由 SSD 控制器通过磨损均衡算法实现，文件系统仅能通过 Trim 指令辅助，并非直接控制。\n\n正确答案：B（确定盘块大小）‌\n文件系统通过逻辑格式化统一管理存储空间，为 HDD 和 SSD 定义逻辑块大小，这是两者共有的功能。",
    difficulty: "medium",
    tags: ["磁盘概念", "操作系统", "2025 年真题"],
    sourceKey: "csgraduates-408",
