    options: [{ key: "A", text: "Tcs​>Tms​>Tps​" }, { key: "B", text: "Tms​>Tps​>Tcs​" }, { key: "C", text: "Tms​>Tcs​>Tps​" }, { key: "D", text: "Tps​>Tms​>Tcs​" }],
