    topicKey: "ex408g-net-datalink",
    type: "single",
    stem: "现有一 10BaseT 以太网，甲乙处于同一个冲突域，连续发生 11 次冲突，甲再次发送的最大时间间隔为（）。",
    options: [{ key: "A", text: "0.512ms" }, { key: "B", text: "0.5632ms" }, { key: "C", text: "52.3776ms" }, { key: "D", text: "104.8064ms" }],
    answer: ["C"],
    explanation: "在以太网中，当发生冲突时，发送节点将执行指数退避算法。在这个算法中，节点在重传之前会等待一个随机的时间间隔，这个时间间隔是以时隙（slot time）为单位计算的。\n\n对于 10BaseT 以太网，时隙时间（slot time）为 51.2 微秒（0.0512 毫秒）。\n\n在指数退避算法中，第 n 次重传时，节点会从\n0\n到\n2n−1\n的范围内随机选择一个整数 k，然后等待 k 个时隙的时间。需要注意的是，当 n 达到 10 或更大时，退避范围的上限固定为 1023（即\n210−1\n）。\n\n在题目中，已经发生了 11 次冲突，意味着这是第 12 次重传尝试。因此，n = 11，但因为\nn≥10\n的时候，k 的范围是 0 到 1023。\n\n因此，甲再次发送的最大时间间隔为 1023 个时隙时间，即：\n\n1023×51.2μs=52377.6μs=52.3776ms",
