    explanation: "【解析】\n\n这是一道森林转二叉树的经典题。\n\n关键结论（必须掌握）\n\n设森林中第\ni\n棵树对应二叉树的高度为\nhi​\n，则森林转换为二叉树后：\n\n二叉树高度=imax​{hi​+(i−1)}​\n\n其中：\n\n第\ni\n棵树表示森林中从左到右的第\ni\n棵树；\n\n(i−1)\n来自各棵树根结点之间形成的右兄弟链；\n\n为了使最终高度最小，应将高度较大的树排在前面。\n\n先计算每棵树对应二叉树的最小高度\n\n对于一棵有\nn\n个结点的普通树，采用左孩子-右兄弟表示法转换为二叉树后，由于根结点没有右孩子，因此最小高度为：\n\nhmin​=1+⌈log2​n⌉\n\n各棵树对应二叉树的最小高度如下：\n\n结点数\n\n最小高度\n\n7\n\n1+⌈log2​7⌉=4\n\n5\n\n1+⌈log2​5⌉=4\n\n4\n\n1+⌈log2​4⌉=3\n\n3\n\n1+⌈log2​3⌉=3\n\n2\n\n1+⌈log2​2⌉=2\n\n按最优顺序（高度从大到小）排列：\n\n4,4,3,3,2\n\n计算最终二叉树高度\n\ni\n\n树高\nhi​\n\nhi​+(i−1)\n\n1\n\n4\n\n4\n\n2\n\n4\n\n5\n\n3\n\n3\n\n5\n\n4\n\n3\n\n6\n\n5\n\n2\n\n6\n\n最大值为：\n\n6​\n\n因此答案为 B。",
    difficulty: "medium",
    tags: ["二叉树和森林的转换", "数据结构", "2026 年真题"],
