    topicKey: "ex408g-ds-graph",
    type: "single",
    stem: "设有序向图 G=(V,E) ，其中顶点集 V 的大小为 n=∣V∣ ，每条边 e∈E 都标记有一个唯一的字符（不同边可标记相同字符）。定义字符串集 S 为：所有由 G 中任意一条路径（路径可包含单个顶点，对应空字符串）上的边标记按顺序拼接而成的字符串的集合。以下说法错误的是（）",
    options: [{ key: "A", text: "若 G 无环，则 S 是有限集" }, { key: "B", text: "若 G 无环，则 S 中存在长度为 n 的字符串" }, { key: "C", text: "若 G 有环，则 S 中存在长度大于 n 的字符串" }, { key: "D", text: "若 G 有环，则 S 中存在长度小于 2n 的字符串" }],
    answer: ["B"],
    explanation: "【解析】\n对于选项 A：若图 G 无环，则任意路径不能重复经过顶点，否则会形成环，因此最长路径的边数不超过\nn−1\n。由于图是有限的，所有可能的路径数量有限，每条路径对应一个字符串（可能重复），但字符串集合 S 由有限个字符串组成，故 S 是有限集。A 正确。\n\n对于选项 B：若图 G 无环，则任意路径最多经过\nn\n个不同的顶点，因此边数最多为\nn−1\n，对应的字符串长度最多为\nn−1\n。所以 S 中不可能存在长度为\nn\n的字符串。B 错误。\n\n对于选项 C：若图 G 有环，则存在一个环，可以从环上某点出发沿环行走任意多圈，得到任意长的路径，从而产生长度大于\nn\n的字符串。C 正确。\n\n对于选项 D：若图 G 有环，S 中至少包含空字符串（长度为\n0\n），而\n0<2n\n（\nn≥1\n），因此存在长度小于\n2n\n的字符串。D 正确。\n\n综上，说法错误的是 B。",
