    answer: ["D"],
    explanation: "【解析】\n首先，根据香农定理，信道容量为\n\nC=Blog2​(1+S/N)\n\n其中带宽\nB=200kHz=2×105Hz\n，信噪比\nS/N=1023\n。\n计算\n1+1023=1024\n，且\nlog2​(1024)=10\n，因此\n\nC=2×105×10=2×106bit/s=2Mbps.\n\n分组长度为\n1500B\n，即\n1500×8=12000bits\n。\n传输时延是分组长度除以数据传输速率，在理想情况下，最大速率为信道容量，故最小传输时延为\n\nT=2×10612000​=0.006s=6ms.\n\n因此，发送该分组的传输时延至少是 6 ms。",
